#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n >> m;
    long long center = (long long)n * (n - 1) / 2;
    long long max_range = (long long)n * (n - 1);
    vector<vector<long long>> dp_table(n + 1, vector<long long>(max_range + 1, 0));
    vector<vector<long long>> dp1_table(n + 1, vector<long long>(max_range + 1, 0));
    dp_table[1][center] = 1;
    for (int i = 2; i <= n; ++i) {
        long long min_x = center - (long long)(i - 1) * (i - 2) / 2;
        long long max_x = center + (long long)(i - 1) * (i - 2) / 2;
        for (long long x = min_x; x <= max_x; ++x) {
            for (int d = -i + 1; d < i; ++d) {
                long long idx = x + d;
                if (0 <= idx && idx <= max_range) {
                    dp_table[i][idx] = (dp_table[i][idx] + dp_table[i - 1][x] * (i - abs(d))) % m;
                }
            }
        }
        for (long long x = min_x; x <= max_x; ++x) {
            dp1_table[i][x] = (dp1_table[i - 1][x] * i) % m;
        }
        for (long long x = min_x; x <= max_x; ++x) {
            for (int d = 1; d < i; ++d) {
                long long idx = x - d;
                if (0 <= idx && idx <= max_range) {
                    dp1_table[i][idx] = (dp1_table[i][idx] + dp_table[i - 1][x] * (i - d)) % m;
                }
            }
        }
    }
    long long result = 0;
    for (long long x = center + 1; x <= max_range; ++x) {
        result = (result + dp1_table[n][x]) % m;
    }
    cout << result << "\n";
    return 0;
}
